def get_venue_symbols_for_pipeline() -> dict:
    """Return VENUE_SYMBOLS format for market_data_pipeline.py."""
    result = {}
    for venue, companies in COMPANIES.items():
        result[venue] = {sym: {"price": d["price"], "vol": d["vol"]} for sym, d in companies.items()}
    return result


def get_all_companies_flat() -> list:
    """Return flat list of all companies with venue attached."""
    rows = []
    for venue, companies in COMPANIES.items():
        for sym, d in companies.items():
            rows.append({"venue": venue, "symbol": sym, **d})
    return rows


def get_top_companies_js() -> str:
    """Render the TOP_COMPANIES JS object for embedding in the portal."""
    lines = ["const TOP_COMPANIES = {"]
    for venue, companies in COMPANIES.items():
        lines.append(f"  {venue}: [")
        for sym, d in companies.items():
            name_esc = d["name"].replace("'", "\\'")
            lines.append(f"    {{t:'{sym}', n:'{name_esc}', s:'{d['sector']}'}},")
        lines.append("  ],")
    lines.append("};")
    return "\n".join(lines)
